// AUTO-GENERATO da scripts/build-manuale-cards.mjs — non modificare a mano.
// Fonte: public/regole.html (5 gruppi, verbatim x5 lingue).
import type { Lang } from "@/lib/i18n";

export type RegoleCard = { id: string; index: string; icon: string; image: string | null; tag: Record<Lang, string>; title: Record<Lang, string>; body: Record<Lang, string> };

export const regoleCards: RegoleCard[] = [{"id":"rules-arrival","index":"001","icon":"KeyRound","image":null,"tag":{"it":"Arrivo","en":"Arrival","es":"Llegada","fr":"Arrivée","de":"Ankunft"},"title":{"it":"Arrivo, partenza e chiavi","en":"Arrival, departure and keys","es":"Llegada, salida y llaves","fr":"Arrivée, départ et clés","de":"Ankunft, Abreise und Schlüssel"},"body":{"it":"<article class=\"rule-row\"><h4>Check-in</h4><p>Dalle 15:00. L’ingresso anticipato è possibile solo previa disponibilità e accordo con l’host.</p></article><article class=\"rule-row\"><h4>Check-out</h4><p>Entro le 10:00. È prevista una tolleranza di 15 minuti: dal 16° minuto di ritardo non concordato si applicano i primi 20 € della prima ora, trattenuti dal deposito cauzionale.</p></article><article class=\"rule-row\"><h4>Restituzione delle chiavi</h4><p>Al check-out, salvo diverse indicazioni, lasciare le chiavi nella buca delle lettere con la scritta “A Casa di Marco”.</p></article><article class=\"rule-row\"><h4>Chiavi</h4><p>Custodirle con attenzione. In caso di smarrimento potrà essere richiesto un rimborso di 25 €. Se fosse necessario sostituire serrature o dispositivi di accesso, potranno essere richiesti anche i relativi costi. Gli importi potranno essere trattenuti dal deposito cauzionale.</p></article><article class=\"rule-row\"><h4>Parcheggio</h4><p>Utilizzare esclusivamente gli spazi indicati dall’host, senza bloccare accessi o passaggi.</p></article>","en":"<article class=\"rule-row\"><h4>Check-in</h4><p>From 15:00. Early arrival is possible only subject to availability and agreement with the host.</p></article><article class=\"rule-row\"><h4>Check-out</h4><p>By 10:00. A 15-minute grace period applies: from the 16th minute of an unagreed delay, the first €20 of the first hour are deducted from the security deposit.</p></article><article class=\"rule-row\"><h4>Returning the keys</h4><p>At check-out, unless instructed otherwise, leave the keys in the mailbox marked “A Casa di Marco”.</p></article><article class=\"rule-row\"><h4>Keys</h4><p>Keep the keys safe. Lost keys may incur a €25 reimbursement. If locks or access devices need replacing, their costs may also be charged. These amounts may be deducted from the security deposit.</p></article><article class=\"rule-row\"><h4>Parking</h4><p>Use only the spaces indicated by the host, without blocking entrances or passageways.</p></article>","es":"<article class=\"rule-row\"><h4>Check-in</h4><p>Desde las 15:00. La entrada anticipada solo es posible según disponibilidad y previo acuerdo con el anfitrión.</p></article><article class=\"rule-row\"><h4>Check-out</h4><p>Antes de las 10:00. Hay un período de gracia de 15 minutos: a partir del minuto 16 de un retraso no acordado se retienen los primeros 20 € de la primera hora del depósito de garantía.</p></article><article class=\"rule-row\"><h4>Entrega de llaves</h4><p>Al salir, salvo otras indicaciones, dejar las llaves en el buzón con el nombre “A Casa di Marco”.</p></article><article class=\"rule-row\"><h4>Llaves</h4><p>Guardar las llaves con cuidado. Su pérdida podrá conllevar un reembolso de 25 €. Si es necesario cambiar cerraduras o dispositivos de acceso, también podrán cobrarse esos costes y deducirse del depósito de garantía.</p></article><article class=\"rule-row\"><h4>Aparcamiento</h4><p>Usar solo los espacios indicados por el anfitrión, sin bloquear accesos ni pasos.</p></article>","fr":"<article class=\"rule-row\"><h4>Check-in</h4><p>À partir de 15 h. Une arrivée anticipée est possible uniquement selon disponibilité et avec l’accord de l’hôte.</p></article><article class=\"rule-row\"><h4>Check-out</h4><p>Avant 10 h. Un délai de grâce de 15 minutes s’applique : à partir de la 16e minute de retard non convenu, les premiers 20 € de la première heure sont retenus sur le dépôt de garantie.</p></article><article class=\"rule-row\"><h4>Remise des clés</h4><p>Au départ, sauf indication contraire, déposez les clés dans la boîte aux lettres portant le nom « A Casa di Marco ».</p></article><article class=\"rule-row\"><h4>Clés</h4><p>Gardez les clés avec soin. En cas de perte, un remboursement de 25 € pourra être demandé, ainsi que les frais de remplacement des serrures ou dispositifs d’accès si nécessaire. Ces montants pourront être retenus sur le dépôt de garantie.</p></article><article class=\"rule-row\"><h4>Parking</h4><p>Utilisez uniquement les places indiquées par l’hôte, sans bloquer accès ou passages.</p></article>","de":"<article class=\"rule-row\"><h4>Check-in</h4><p>Ab 15:00 Uhr. Ein früherer Zugang ist nur nach Verfügbarkeit und Absprache mit dem Gastgeber möglich.</p></article><article class=\"rule-row\"><h4>Check-out</h4><p>Bis 10:00 Uhr. Es gilt eine Toleranz von 15 Minuten: ab der 16. Minute einer nicht vereinbarten Verspätung werden die ersten 20 € der ersten Stunde von der Kaution einbehalten.</p></article><article class=\"rule-row\"><h4>Schlüsselrückgabe</h4><p>Beim Check-out die Schlüssel, sofern nicht anders angewiesen, in den Briefkasten mit der Aufschrift „A Casa di Marco“ legen.</p></article><article class=\"rule-row\"><h4>Schlüssel</h4><p>Schlüssel sorgfältig aufbewahren. Bei Verlust können 25 € sowie gegebenenfalls die Kosten für neue Schlösser oder Zugangssysteme berechnet und von der Kaution einbehalten werden.</p></article><article class=\"rule-row\"><h4>Parken</h4><p>Nur die vom Gastgeber angegebenen Stellplätze nutzen; Zugänge und Wege nicht blockieren.</p></article>"}},{"id":"rules-people","index":"002","icon":"Users","image":null,"tag":{"it":"Ospiti","en":"Guests","es":"Huéspedes","fr":"Voyageurs","de":"Gäste"},"title":{"it":"Ospiti e tranquillità","en":"Guests and quiet","es":"Huéspedes y tranquilidad","fr":"Voyageurs et tranquillité","de":"Gäste und Ruhe"},"body":{"it":"<article class=\"rule-row\"><h4>Ospiti</h4><p>Possono soggiornare solo le persone indicate nella prenotazione. Ospiti aggiuntivi o visitatori devono essere preventivamente autorizzati dall’host.</p></article><article class=\"rule-row\"><h4>Party ed eventi</h4><p>Non sono consentiti.</p></article><article class=\"rule-row\"><h4>Silenzio</h4><p>Dalle 23:00 alle 7:00. Evitare musica alta, urla, schiamazzi e rumori molesti.</p></article><article class=\"rule-row\"><h4>Vicinato</h4><p>Rispettare la tranquillità della zona e mantenere un comportamento rispettoso verso i residenti.</p></article><article class=\"rule-row\"><h4>Fumo</h4><p>Vietato all’interno della casa. È consentito solo negli spazi esterni, utilizzando gli appositi posacenere.</p></article><article class=\"rule-row\"><h4>Animali</h4><p>Non ammessi, salvo accordi preventivi con l’host.</p></article><article class=\"rule-row\"><h4>Rispetto reciproco</h4><p>Trattare casa, host e vicini con rispetto e gentilezza. Rispetto chiama rispetto. ❤️</p></article>","en":"<article class=\"rule-row\"><h4>Guests</h4><p>Only the people listed in the booking may stay. Additional guests or visitors require prior authorisation from the host.</p></article><article class=\"rule-row\"><h4>Parties and events</h4><p>Not permitted.</p></article><article class=\"rule-row\"><h4>Quiet hours</h4><p>From 23:00 to 07:00. Avoid loud music, shouting and disturbing noise.</p></article><article class=\"rule-row\"><h4>Neighbours</h4><p>Respect the peace of the area and behave respectfully towards residents.</p></article><article class=\"rule-row\"><h4>Smoking</h4><p>Not allowed inside the house. Permitted only outdoors, using the ashtrays provided.</p></article><article class=\"rule-row\"><h4>Pets</h4><p>Not allowed unless agreed in advance with the host.</p></article><article class=\"rule-row\"><h4>Mutual respect</h4><p>Treat the house, hosts and neighbours with respect and kindness. Respect brings respect. ❤️</p></article>","es":"<article class=\"rule-row\"><h4>Huéspedes</h4><p>Solo pueden alojarse las personas indicadas en la reserva. Los huéspedes adicionales o visitantes requieren autorización previa del anfitrión.</p></article><article class=\"rule-row\"><h4>Fiestas y eventos</h4><p>No están permitidos.</p></article><article class=\"rule-row\"><h4>Horario de silencio</h4><p>De las 23:00 a las 7:00. Evitar música alta, gritos y ruidos molestos.</p></article><article class=\"rule-row\"><h4>Vecindario</h4><p>Respetar la tranquilidad de la zona y comportarse con respeto hacia los residentes.</p></article><article class=\"rule-row\"><h4>Tabaco</h4><p>Prohibido dentro de la casa. Solo se permite en el exterior, utilizando los ceniceros.</p></article><article class=\"rule-row\"><h4>Animales</h4><p>No admitidos, salvo acuerdo previo con el anfitrión.</p></article><article class=\"rule-row\"><h4>Respeto mutuo</h4><p>Tratar la casa, al anfitrión y a los vecinos con respeto y amabilidad. El respeto genera respeto. ❤️</p></article>","fr":"<article class=\"rule-row\"><h4>Voyageurs</h4><p>Seules les personnes indiquées dans la réservation peuvent séjourner. Les voyageurs supplémentaires ou visiteurs doivent être autorisés à l’avance par l’hôte.</p></article><article class=\"rule-row\"><h4>Fêtes et événements</h4><p>Ils ne sont pas autorisés.</p></article><article class=\"rule-row\"><h4>Heures de calme</h4><p>De 23 h à 7 h. Évitez la musique forte, les cris et les bruits gênants.</p></article><article class=\"rule-row\"><h4>Voisinage</h4><p>Respectez la tranquillité du quartier et les résidents.</p></article><article class=\"rule-row\"><h4>Tabac</h4><p>Interdit à l’intérieur. Autorisé uniquement à l’extérieur, en utilisant les cendriers prévus.</p></article><article class=\"rule-row\"><h4>Animaux</h4><p>Non admis, sauf accord préalable avec l’hôte.</p></article><article class=\"rule-row\"><h4>Respect mutuel</h4><p>Traitez la maison, les hôtes et les voisins avec respect et gentillesse. Le respect appelle le respect. ❤️</p></article>","de":"<article class=\"rule-row\"><h4>Gäste</h4><p>Nur die in der Buchung angegebenen Personen dürfen übernachten. Zusätzliche Gäste oder Besucher benötigen die vorherige Erlaubnis des Gastgebers.</p></article><article class=\"rule-row\"><h4>Partys und Veranstaltungen</h4><p>Nicht gestattet.</p></article><article class=\"rule-row\"><h4>Ruhezeiten</h4><p>Von 23:00 bis 7:00 Uhr. Laute Musik, Rufen und störenden Lärm vermeiden.</p></article><article class=\"rule-row\"><h4>Nachbarschaft</h4><p>Die Ruhe der Umgebung achten und sich gegenüber den Anwohnern respektvoll verhalten.</p></article><article class=\"rule-row\"><h4>Rauchen</h4><p>Im Haus verboten. Nur im Außenbereich unter Verwendung der bereitgestellten Aschenbecher erlaubt.</p></article><article class=\"rule-row\"><h4>Haustiere</h4><p>Nicht erlaubt, außer nach vorheriger Absprache mit dem Gastgeber.</p></article><article class=\"rule-row\"><h4>Gegenseitiger Respekt</h4><p>Haus, Gastgeber und Nachbarn mit Respekt und Freundlichkeit behandeln. Respekt verdient Respekt. ❤️</p></article>"}},{"id":"rules-clean","index":"003","icon":"Sparkles","image":null,"tag":{"it":"Pulizia","en":"Cleaning","es":"Limpieza","fr":"Propreté","de":"Sauberkeit"},"title":{"it":"Pulizia, rifiuti e biancheria","en":"Cleaning, waste and linen","es":"Limpieza, residuos y ropa","fr":"Propreté, déchets et linge","de":"Sauberkeit, Müll und Wäsche"},"body":{"it":"<article class=\"rule-row\"><h4>Raccolta differenziata</h4><p>È obbligatorio rispettare le indicazioni presenti in struttura e utilizzare gli appositi contenitori.</p></article><article class=\"rule-row\"><h4>Smaltimento dei rifiuti</h4><p>In caso di rifiuti non differenziati, lasciati in modo improprio o che richiedano un intervento straordinario, potrà essere richiesto un contributo fino a 50 €, che potrà essere trattenuto dal deposito cauzionale.</p></article><article class=\"rule-row\"><h4>Rifiuti organici</h4><p>Non devono essere lasciati a lungo all’interno dell’abitazione e devono essere smaltiti negli appositi contenitori.</p></article><article class=\"rule-row\"><h4>Pulizia al check-out</h4><p>Non è necessario effettuare le pulizie finali, ma la casa deve essere lasciata in condizioni decorose.</p></article><article class=\"rule-row\"><h4>Pulizie straordinarie</h4><p>In caso di sporco eccessivo, rifiuti abbandonati, macchie importanti o condizioni che richiedano un intervento oltre la normale pulizia, potranno essere richiesti costi aggiuntivi, che potranno essere trattenuti dal deposito cauzionale.</p></article><article class=\"rule-row\"><h4>Asciugamani e biancheria</h4><p>Non devono essere portati fuori dalla struttura né utilizzati per pulire scarpe, pavimenti o altre superfici.</p></article><article class=\"rule-row\"><h4>Asciugamani al check-out</h4><p>Se possibile, lasciare gli asciugamani utilizzati nella cesta dei panni sporchi.</p></article>","en":"<article class=\"rule-row\"><h4>Waste sorting</h4><p>Follow the waste-sorting instructions at the property and use the designated bins.</p></article><article class=\"rule-row\"><h4>Waste disposal</h4><p>Unsorted or improperly left waste, or waste requiring exceptional handling, may incur a charge of up to €50, which may be deducted from the security deposit.</p></article><article class=\"rule-row\"><h4>Organic waste</h4><p>Do not leave organic waste inside for long; dispose of it in the designated bins.</p></article><article class=\"rule-row\"><h4>Condition at check-out</h4><p>Final cleaning is not required, but leave the house in a reasonably tidy condition.</p></article><article class=\"rule-row\"><h4>Extra cleaning</h4><p>Excessive dirt, abandoned waste, significant stains or conditions requiring more than normal cleaning may incur additional costs, which may be deducted from the security deposit.</p></article><article class=\"rule-row\"><h4>Towels and linen</h4><p>Do not take them outside the property or use them to clean shoes, floors or other surfaces.</p></article><article class=\"rule-row\"><h4>Towels at check-out</h4><p>If possible, leave used towels in the laundry basket.</p></article>","es":"<article class=\"rule-row\"><h4>Separación de residuos</h4><p>Es obligatorio respetar las indicaciones del alojamiento y usar los contenedores correspondientes.</p></article><article class=\"rule-row\"><h4>Eliminación de residuos</h4><p>Los residuos no separados, dejados de forma inadecuada o que requieran una intervención extraordinaria podrán conllevar un cargo de hasta 50 €, deducible del depósito de garantía.</p></article><article class=\"rule-row\"><h4>Residuos orgánicos</h4><p>No dejarlos durante mucho tiempo dentro de la vivienda; depositarlos en los contenedores correspondientes.</p></article><article class=\"rule-row\"><h4>Limpieza a la salida</h4><p>No es necesario realizar la limpieza final, pero dejar la casa en condiciones decorosas.</p></article><article class=\"rule-row\"><h4>Limpieza extraordinaria</h4><p>La suciedad excesiva, los residuos abandonados, las manchas importantes o las condiciones que requieran más que una limpieza normal podrán generar costes adicionales, deducibles del depósito de garantía.</p></article><article class=\"rule-row\"><h4>Toallas y ropa de cama</h4><p>No sacarlos del alojamiento ni utilizarlos para limpiar zapatos, suelos u otras superficies.</p></article><article class=\"rule-row\"><h4>Toallas a la salida</h4><p>Si es posible, dejar las toallas usadas en la cesta de ropa sucia.</p></article>","fr":"<article class=\"rule-row\"><h4>Tri des déchets</h4><p>Il est obligatoire de respecter les consignes présentes dans le logement et d’utiliser les bacs appropriés.</p></article><article class=\"rule-row\"><h4>Élimination des déchets</h4><p>Les déchets non triés, laissés de manière inappropriée ou nécessitant une intervention exceptionnelle pourront entraîner une contribution allant jusqu’à 50 €, pouvant être retenue sur le dépôt de garantie.</p></article><article class=\"rule-row\"><h4>Déchets organiques</h4><p>Ne les laissez pas longtemps à l’intérieur et déposez-les dans les bacs prévus.</p></article><article class=\"rule-row\"><h4>Propreté au départ</h4><p>Le ménage final n’est pas demandé, mais la maison doit être laissée dans un état convenable.</p></article><article class=\"rule-row\"><h4>Ménage exceptionnel</h4><p>Une saleté excessive, des déchets abandonnés, des taches importantes ou un état nécessitant plus qu’un ménage normal pourront entraîner des frais supplémentaires, pouvant être retenus sur le dépôt de garantie.</p></article><article class=\"rule-row\"><h4>Serviettes et linge</h4><p>Ne les emportez pas hors de la propriété et ne les utilisez pas pour nettoyer chaussures, sols ou autres surfaces.</p></article><article class=\"rule-row\"><h4>Serviettes au départ</h4><p>Si possible, déposez les serviettes utilisées dans le panier à linge sale.</p></article>","de":"<article class=\"rule-row\"><h4>Mülltrennung</h4><p>Die Hinweise zur Mülltrennung in der Unterkunft sind verbindlich; die vorgesehenen Behälter verwenden.</p></article><article class=\"rule-row\"><h4>Müllentsorgung</h4><p>Für ungetrennte, unsachgemäß hinterlassene oder außergewöhnlichen Aufwand erfordernde Abfälle können bis zu 50 € berechnet und von der Kaution einbehalten werden.</p></article><article class=\"rule-row\"><h4>Bioabfälle</h4><p>Nicht längere Zeit im Haus aufbewahren; in den vorgesehenen Behältern entsorgen.</p></article><article class=\"rule-row\"><h4>Sauberkeit beim Check-out</h4><p>Eine Endreinigung ist nicht erforderlich; das Haus muss jedoch in einem ordentlichen Zustand hinterlassen werden.</p></article><article class=\"rule-row\"><h4>Außergewöhnliche Reinigung</h4><p>Bei übermäßiger Verschmutzung, zurückgelassenem Müll, erheblichen Flecken oder Aufwand über die normale Reinigung hinaus können zusätzliche Kosten entstehen und von der Kaution einbehalten werden.</p></article><article class=\"rule-row\"><h4>Handtücher und Wäsche</h4><p>Nicht außerhalb der Unterkunft mitnehmen oder zum Reinigen von Schuhen, Böden oder anderen Oberflächen verwenden.</p></article><article class=\"rule-row\"><h4>Handtücher beim Check-out</h4><p>Benutzte Handtücher nach Möglichkeit in den Wäschekorb legen.</p></article>"}},{"id":"rules-care","index":"004","icon":"House","image":null,"tag":{"it":"Cura","en":"Care","es":"Cuidado","fr":"Soin","de":"Pflege"},"title":{"it":"Cura della casa","en":"Taking care of the house","es":"Cuidado de la casa","fr":"Prendre soin de la maison","de":"Sorgfalt im Haus"},"body":{"it":"<article class=\"rule-row\"><h4>Danni</h4><p>Eventuali danni o rotture devono essere comunicati immediatamente all’host. I costi di riparazione o sostituzione potranno essere addebitati quando il danno è imputabile all’ospite e potranno essere trattenuti dal deposito cauzionale.</p></article><article class=\"rule-row\"><h4>Guasti o problemi</h4><p>Eventuali perdite d’acqua, problemi elettrici o altri malfunzionamenti devono essere segnalati immediatamente. Non effettuare riparazioni autonomamente.</p></article><article class=\"rule-row\"><h4>Problemi durante il soggiorno</h4><p>Se qualcosa non va, contattare subito l’host per permetterci di intervenire e risolvere il problema durante il soggiorno.</p></article><article class=\"rule-row\"><h4>Mobili e arredi</h4><p>Non spostare mobili, letti, elettrodomestici o elementi d’arredo senza autorizzazione.</p></article><article class=\"rule-row\"><h4>Elettrodomestici</h4><p>Utilizzare gli apparecchi presenti in casa esclusivamente per il loro normale utilizzo.</p></article><article class=\"rule-row\"><h4>Spazi esterni</h4><p>Utilizzare giardino e veranda con cura e non lasciare rifiuti, mozziconi o oggetti personali all’esterno.</p></article><article class=\"rule-row\"><h4>Dotazioni della casa</h4><p>Stoviglie, utensili, biancheria, asciugamani e altri oggetti presenti nell’alloggio non devono essere portati fuori dalla struttura.</p></article><article class=\"rule-row\"><h4>Rispetto della proprietà</h4><p>Trattare la casa con cura. In caso di uso improprio, danneggiamenti intenzionali o violazioni gravi delle regole, potranno essere richiesti i relativi costi, che potranno essere trattenuti dal deposito cauzionale.</p></article><article class=\"rule-row\"><h4>Prezzi e servizi extra</h4><p>Le tariffe concordate per soggiorno ed eventuali servizi aggiuntivi non sono trattabili dopo l’accettazione.</p></article>","en":"<article class=\"rule-row\"><h4>Damage</h4><p>Report any damage or breakage to the host immediately. Repair or replacement costs may be charged when the guest is responsible and may be deducted from the security deposit.</p></article><article class=\"rule-row\"><h4>Faults or problems</h4><p>Report water leaks, electrical problems or other faults immediately. Do not carry out repairs yourself.</p></article><article class=\"rule-row\"><h4>Problems during your stay</h4><p>If something is wrong, contact the host immediately so we can address and resolve it during your stay.</p></article><article class=\"rule-row\"><h4>Furniture</h4><p>Do not move furniture, beds, appliances or furnishings without permission.</p></article><article class=\"rule-row\"><h4>Appliances</h4><p>Use appliances only for their intended purpose.</p></article><article class=\"rule-row\"><h4>Outdoor spaces</h4><p>Use the garden and veranda carefully and do not leave waste, cigarette ends or personal belongings outside.</p></article><article class=\"rule-row\"><h4>House equipment</h4><p>Do not take crockery, utensils, linen, towels or other accommodation items outside the property.</p></article><article class=\"rule-row\"><h4>Respect for the property</h4><p>Treat the house with care. Misuse, intentional damage or serious rule violations may result in related costs being charged and deducted from the security deposit.</p></article><article class=\"rule-row\"><h4>Prices and extra services</h4><p>Agreed rates for the stay and any additional services are not negotiable after acceptance.</p></article>","es":"<article class=\"rule-row\"><h4>Daños</h4><p>Comunicar inmediatamente los daños o roturas al anfitrión. Cuando sean imputables al huésped, los costes de reparación o sustitución podrán cobrarse y deducirse del depósito de garantía.</p></article><article class=\"rule-row\"><h4>Averías o problemas</h4><p>Comunicar inmediatamente las fugas de agua, los problemas eléctricos u otros fallos. No realizar reparaciones por cuenta propia.</p></article><article class=\"rule-row\"><h4>Problemas durante la estancia</h4><p>Si algo no va bien, contactar inmediatamente con el anfitrión para que podamos resolverlo durante la estancia.</p></article><article class=\"rule-row\"><h4>Muebles</h4><p>No mover muebles, camas, electrodomésticos u otros elementos sin autorización.</p></article><article class=\"rule-row\"><h4>Electrodomésticos</h4><p>Utilizar los aparatos de la casa exclusivamente para su uso normal.</p></article><article class=\"rule-row\"><h4>Espacios exteriores</h4><p>Usar jardín y veranda con cuidado; no dejar residuos, colillas u objetos personales en el exterior.</p></article><article class=\"rule-row\"><h4>Equipamiento</h4><p>No sacar de la propiedad vajilla, utensilios, ropa de cama, toallas ni otros objetos del alojamiento.</p></article><article class=\"rule-row\"><h4>Respeto de la propiedad</h4><p>Tratar la casa con cuidado. El uso indebido, los daños intencionados o las infracciones graves podrán generar costes, deducibles del depósito de garantía.</p></article><article class=\"rule-row\"><h4>Precios y servicios extra</h4><p>Las tarifas acordadas para la estancia y los servicios adicionales no son negociables después de su aceptación.</p></article>","fr":"<article class=\"rule-row\"><h4>Dégâts</h4><p>Signalez immédiatement tout dommage ou casse à l’hôte. Les frais de réparation ou remplacement pourront être facturés si le voyageur est responsable et retenus sur le dépôt de garantie.</p></article><article class=\"rule-row\"><h4>Pannes ou problèmes</h4><p>Signalez immédiatement toute fuite d’eau, tout problème électrique ou autre dysfonctionnement. N’effectuez pas de réparations vous-même.</p></article><article class=\"rule-row\"><h4>Problèmes pendant le séjour</h4><p>Si quelque chose ne va pas, contactez l’hôte immédiatement afin de nous permettre d’intervenir pendant le séjour.</p></article><article class=\"rule-row\"><h4>Mobilier</h4><p>Ne déplacez pas meubles, lits, appareils ou éléments de décoration sans autorisation.</p></article><article class=\"rule-row\"><h4>Appareils</h4><p>Utilisez les appareils uniquement pour leur usage prévu.</p></article><article class=\"rule-row\"><h4>Espaces extérieurs</h4><p>Utilisez le jardin et la véranda avec soin, sans laisser déchets, mégots ou objets personnels à l’extérieur.</p></article><article class=\"rule-row\"><h4>Équipements de la maison</h4><p>Vaisselle, ustensiles, linge, serviettes et autres objets du logement ne doivent pas être emportés hors de la propriété.</p></article><article class=\"rule-row\"><h4>Respect de la propriété</h4><p>Prenez soin de la maison. Un usage inapproprié, des dommages intentionnels ou des violations graves pourront entraîner des frais, pouvant être retenus sur le dépôt de garantie.</p></article><article class=\"rule-row\"><h4>Tarifs et services supplémentaires</h4><p>Les tarifs convenus pour le séjour et les services supplémentaires ne sont pas négociables après acceptation.</p></article>","de":"<article class=\"rule-row\"><h4>Schäden</h4><p>Schäden oder Defekte sofort dem Gastgeber melden. Ist der Gast verantwortlich, können Reparatur- oder Ersatzkosten berechnet und von der Kaution einbehalten werden.</p></article><article class=\"rule-row\"><h4>Defekte oder Probleme</h4><p>Wasserlecks, elektrische Probleme und andere Störungen sofort melden. Keine eigenständigen Reparaturen durchführen.</p></article><article class=\"rule-row\"><h4>Probleme während des Aufenthalts</h4><p>Bei Problemen sofort den Gastgeber kontaktieren, damit wir während des Aufenthalts helfen können.</p></article><article class=\"rule-row\"><h4>Möbel und Einrichtung</h4><p>Möbel, Betten, Geräte und Einrichtungsgegenstände nicht ohne Erlaubnis umstellen.</p></article><article class=\"rule-row\"><h4>Haushaltsgeräte</h4><p>Geräte ausschließlich bestimmungsgemäß verwenden.</p></article><article class=\"rule-row\"><h4>Außenbereiche</h4><p>Garten und Veranda sorgfältig nutzen; keine Abfälle, Zigarettenstummel oder persönlichen Gegenstände draußen hinterlassen.</p></article><article class=\"rule-row\"><h4>Ausstattung</h4><p>Geschirr, Utensilien, Wäsche, Handtücher und andere Gegenstände der Unterkunft nicht außerhalb des Grundstücks mitnehmen.</p></article><article class=\"rule-row\"><h4>Respekt vor dem Eigentum</h4><p>Das Haus sorgfältig behandeln. Bei unsachgemäßer Nutzung, absichtlichen Schäden oder schweren Regelverstößen können entsprechende Kosten berechnet und von der Kaution einbehalten werden.</p></article><article class=\"rule-row\"><h4>Preise und Zusatzleistungen</h4><p>Vereinbarte Preise für den Aufenthalt und Zusatzleistungen sind nach Annahme nicht verhandelbar.</p></article>"}},{"id":"rules-safe","index":"005","icon":"Zap","image":null,"tag":{"it":"Energia","en":"Energy","es":"Energía","fr":"Énergie","de":"Energie"},"title":{"it":"Energia e sicurezza","en":"Energy and safety","es":"Energía y seguridad","fr":"Énergie et sécurité","de":"Energie und Sicherheit"},"body":{"it":"<article class=\"rule-row\"><h4>Energia</h4><p>Quando si esce dalla struttura, spegnere luci, aria condizionata, TV e altri dispositivi elettrici non necessari.</p></article><article class=\"rule-row\"><h4>Aria condizionata</h4><p>Non deve essere lasciata accesa quando nessuno si trova nell’alloggio e va utilizzata preferibilmente con porte e finestre chiuse.</p></article><article class=\"rule-row\"><h4>Sicurezza</h4><p>Prima di uscire assicurarsi che porte e finestre siano correttamente chiuse.</p></article><article class=\"rule-row\"><h4>Cucina</h4><p>Non lasciare fornelli, forno o altri apparecchi accesi senza sorveglianza.</p></article><article class=\"rule-row\"><h4>Attività pericolose</h4><p>Non sono consentiti giochi con palloni, sport o attività che possano causare danni all’interno della casa.</p></article><article class=\"rule-row\"><h4>Emergenze</h4><p>In caso di emergenza chiamare il 112 e avvisare immediatamente l’host.</p></article>","en":"<article class=\"rule-row\"><h4>Energy</h4><p>When leaving, turn off lights, air conditioning, TV and unnecessary electrical devices.</p></article><article class=\"rule-row\"><h4>Air conditioning</h4><p>Do not leave it on when nobody is in the accommodation; preferably use it with doors and windows closed.</p></article><article class=\"rule-row\"><h4>Security</h4><p>Before leaving, make sure doors and windows are properly closed.</p></article><article class=\"rule-row\"><h4>Kitchen</h4><p>Do not leave the hob, oven or other appliances on unattended.</p></article><article class=\"rule-row\"><h4>Dangerous activities</h4><p>Ball games, sports or activities that could cause damage inside the house are not allowed.</p></article><article class=\"rule-row\"><h4>Emergencies</h4><p>In an emergency, call 112 and inform the host immediately.</p></article>","es":"<article class=\"rule-row\"><h4>Energía</h4><p>Al salir, apagar luces, aire acondicionado, televisión y dispositivos eléctricos innecesarios.</p></article><article class=\"rule-row\"><h4>Aire acondicionado</h4><p>No dejarlo encendido cuando no haya nadie en el alojamiento; utilizarlo preferiblemente con puertas y ventanas cerradas.</p></article><article class=\"rule-row\"><h4>Seguridad</h4><p>Antes de salir, asegurarse de que puertas y ventanas estén bien cerradas.</p></article><article class=\"rule-row\"><h4>Cocina</h4><p>No dejar fogones, horno u otros aparatos encendidos sin vigilancia.</p></article><article class=\"rule-row\"><h4>Actividades peligrosas</h4><p>No se permiten juegos con pelotas, deportes o actividades que puedan causar daños dentro de la casa.</p></article><article class=\"rule-row\"><h4>Emergencias</h4><p>En caso de emergencia, llamar al 112 y avisar inmediatamente al anfitrión.</p></article>","fr":"<article class=\"rule-row\"><h4>Énergie</h4><p>En sortant, éteignez lumières, climatisation, télévision et appareils électriques non nécessaires.</p></article><article class=\"rule-row\"><h4>Climatisation</h4><p>Ne la laissez pas allumée en votre absence et utilisez-la de préférence avec les portes et fenêtres fermées.</p></article><article class=\"rule-row\"><h4>Sécurité</h4><p>Avant de sortir, vérifiez que portes et fenêtres sont correctement fermées.</p></article><article class=\"rule-row\"><h4>Cuisine</h4><p>Ne laissez pas plaques, four ou autres appareils allumés sans surveillance.</p></article><article class=\"rule-row\"><h4>Activités dangereuses</h4><p>Les jeux de ballon, sports et activités pouvant causer des dommages à l’intérieur ne sont pas autorisés.</p></article><article class=\"rule-row\"><h4>Urgences</h4><p>En cas d’urgence, appelez le 112 et prévenez immédiatement l’hôte.</p></article>","de":"<article class=\"rule-row\"><h4>Energie</h4><p>Beim Verlassen Licht, Klimaanlage, Fernseher und nicht benötigte elektrische Geräte ausschalten.</p></article><article class=\"rule-row\"><h4>Klimaanlage</h4><p>Nicht eingeschaltet lassen, wenn niemand in der Unterkunft ist; möglichst bei geschlossenen Türen und Fenstern nutzen.</p></article><article class=\"rule-row\"><h4>Sicherheit</h4><p>Vor dem Verlassen sicherstellen, dass Türen und Fenster richtig geschlossen sind.</p></article><article class=\"rule-row\"><h4>Küche</h4><p>Herd, Backofen und andere eingeschaltete Geräte nicht unbeaufsichtigt lassen.</p></article><article class=\"rule-row\"><h4>Gefährliche Aktivitäten</h4><p>Ballspiele, Sport und Aktivitäten, die im Haus Schäden verursachen können, sind nicht gestattet.</p></article><article class=\"rule-row\"><h4>Notfälle</h4><p>Im Notfall 112 anrufen und sofort den Gastgeber informieren.</p></article>"}}];
